def find_path(graph, start, goal):
    def dfs(node, path, visited):
        if node == goal:
            return path
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                new_path = dfs(neighbor, path + [neighbor], visited)
                if new_path:
                    return new_path
        return None

    return dfs(start, [start], set())

