def find_path(graph, start, goal):
    def dfs(current, path):
        path.append(current)
        if current == goal:
            return path
        for neighbor in graph[current]:
            if neighbor not in path:
                new_path = dfs(neighbor, path.copy())  # Use path.copy() to avoid modifying the original path during recursion
                if new_path:
                    return new_path
        return None

    return dfs(start, [])

